In MQL5, you can programmatically set your stop loss to be 1% of your trading balance. Here's how to do it:

## Method 1: Calculate Stop Loss Based on Position Size

```mql5
// Function to calculate stop loss price based on 1% risk
double CalculateStopLoss(string symbol, ENUM_ORDER_TYPE orderType, double entryPrice, double riskPercent = 1.0)
{
    // Get account balance
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);

    // Calculate risk amount (1% of balance)
    double riskAmount = balance * (riskPercent / 100.0);

    // Get symbol information
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double lotSize = 0.1; // Your position size

    // Calculate points for stop loss
    double stopLossPoints = (riskAmount / (lotSize * tickValue)) * tickSize;

    double stopLossPrice = 0;

    if(orderType == ORDER_TYPE_BUY)
    {
        stopLossPrice = entryPrice - stopLossPoints;
    }
    else if(orderType == ORDER_TYPE_SELL)
    {
        stopLossPrice = entryPrice + stopLossPoints;
    }

    // Normalize the price
    return NormalizeDouble(stopLossPrice, (int)SymbolInfoInteger(symbol, SYMBOL_DIGITS));
}
```

## Method 2: Calculate Position Size Based on Stop Loss Distance

```mql5
// Function to calculate lot size based on 1% risk and fixed stop loss distance
double CalculateLotSize(string symbol, double stopLossPoints, double riskPercent = 1.0)
{
    // Get account balance
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);

    // Calculate risk amount
    double riskAmount = balance * (riskPercent / 100.0);

    // Get symbol information
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    // Calculate lot size
    double lotSize = riskAmount / (stopLossPoints * tickValue);

    // Normalize lot size
    lotSize = MathFloor(lotSize / lotStep) * lotStep;

    // Ensure lot size is within limits
    if(lotSize < minLot) lotSize = minLot;
    if(lotSize > maxLot) lotSize = maxLot;

    return NormalizeDouble(lotSize, 2);
}
```

## Complete Example: Opening a Trade with 1% Risk

```mql5
#include <Trade\Trade.mqh>

CTrade trade;

void OpenTradeWithRiskManagement()
{
    string symbol = _Symbol;
    double riskPercent = 1.0; // 1% risk

    // Get current price
    double ask = SymbolInfoDouble(symbol, SYMBOL_ASK);
    double bid = SymbolInfoDouble(symbol, SYMBOL_BID);

    // Define your stop loss distance in points (example: 50 points)
    double stopLossDistance = 50 * SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Calculate lot size for 1% risk
    double lotSize = CalculateLotSizeAdvanced(symbol, stopLossDistance, riskPercent);

    // Calculate actual stop loss price
    double stopLossPrice = ask - stopLossDistance;

    // Calculate take profit (example: 2:1 risk-reward)
    double takeProfitPrice = ask + (stopLossDistance * 2);

    // Place the trade
    trade.Buy(lotSize, symbol, ask, stopLossPrice, takeProfitPrice, "1% Risk Trade");
}

// Advanced lot size calculation
double CalculateLotSizeAdvanced(string symbol, double stopLossDistance, double riskPercent)
{
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = balance * (riskPercent / 100.0);

    // Convert stop loss distance to points
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);
    double stopLossPoints = stopLossDistance / point;

    // Get contract specifications
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double contractSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_CONTRACT_SIZE);

    // Calculate lot size
    double lotSize = (riskAmount * point) / (stopLossDistance * tickValue / tickSize);

    // Get lot restrictions
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    // Round to nearest lot step
    lotSize = MathRound(lotSize / lotStep) * lotStep;

    // Apply limits
    if(lotSize < minLot) lotSize = minLot;
    if(lotSize > maxLot) lotSize = maxLot;

    return NormalizeDouble(lotSize, 2);
}
```

## Usage in Expert Advisor

```mql5
//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
{
    return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
    // Your trading conditions here
    if(/* your buy condition */)
    {
        ExecuteBuyTrade();
    }
}

void ExecuteBuyTrade()
{
    CTrade trade;
    string symbol = _Symbol;
    double riskPercent = 1.0; // 1% risk

    double ask = SymbolInfoDouble(symbol, SYMBOL_ASK);

    // Define stop loss in points (you can make this dynamic)
    double slPoints = 100; // 100 points stop loss
    double slDistance = slPoints * SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Calculate lot size for 1% risk
    double lots = CalculateLotSizeAdvanced(symbol, slDistance, riskPercent);

    // Set stop loss and take profit prices
    double sl = ask - slDistance;
    double tp = ask + (slDistance * 2); // 2:1 RR ratio

    // Execute trade
    if(trade.Buy(lots, symbol, ask, sl, tp, "1% Risk Management"))
    {
        Print("Trade opened successfully with 1% risk");
    }
    else
    {
        Print("Trade failed: ", trade.ResultRetcode());
    }
}
```

## Key Points:

1. **Always use proper position sizing** - Don't just set a stop loss at 1% away from entry; calculate the lot size so that if the stop loss is hit, you lose only 1% of your balance.

2. **Account for broker specifications** - Different symbols have different tick values, contract sizes, and limitations.

3. **Normalize values** - Always normalize prices and lot sizes according to broker requirements.

4. **Consider spread and slippage** - In real trading, account for spread and potential slippage in your calculations.

5. **Test thoroughly** - Always test your risk management system on a demo account first.

This approach ensures that regardless of the stop loss distance, you're always risking only 1% of your account balance per trade.

